<?php
namespace App\Controllers\Admin;
use App\Core\Controller; use App\Core\Auth; use App\Core\Database; use App\Core\Session; use App\Core\Audit;
final class DonationSettingsController extends Controller
{
    public function index(): void { $u=Auth::requireAdmin(); Auth::enforce('manage_settings'); $total=(int)(Database::one('SELECT COUNT(*) c FROM donation_accounts')['c']??0);$pagination=admin_pager($total,20);$accounts=Database::all('SELECT * FROM donation_accounts ORDER BY sort_order,id LIMIT '.(int)$pagination['per_page'].' OFFSET '.(int)$pagination['offset']); $instr=Database::one('SELECT setting_value FROM settings WHERE setting_group="donation" AND setting_key="instructions"'); $this->view('admin/donation-settings',['user'=>$u,'accounts'=>$accounts,'instructions'=>$instr['setting_value']??'','pagination'=>$pagination,'adminTitle'=>'Donation Settings'],'admin'); }
    public function save(): void { $this->requirePost(); $u=Auth::requireAdmin(); Auth::enforce('manage_settings'); $id=(int)($_POST['id']??0); $title=trim($_POST['title']??'');$bank=trim($_POST['bank_name']??'');$name=trim($_POST['account_name']??'');$number=trim($_POST['account_number']??''); if(!$title||!$bank||!$name||!$number){Session::flash('error','Title, bank, account name and account number are required.');redirect('admin/donation-settings');}
        $p=[$title,$bank,$name,$number,null,null,substr(trim($_POST['branch_name']??''),0,120)?:null,'LKR',substr(trim($_POST['instructions']??''),0,4000)?:null,substr(trim($_POST['contact_name']??''),0,140)?:null,substr(trim($_POST['contact_position']??''),0,120)?:null,substr(trim($_POST['contact_phone']??''),0,50)?:null,filter_var(trim($_POST['contact_email']??''),FILTER_VALIDATE_EMAIL)?:null,isset($_POST['is_active'])?1:0,(int)($_POST['sort_order']??0),(int)$u['id']];
        if($id){ Database::exec('UPDATE donation_accounts SET title=?,bank_name=?,account_name=?,account_number=?,iban=?,swift_code=?,branch_name=?,currency=?,instructions=?,contact_name=?,contact_position=?,contact_phone=?,contact_email=?,is_active=?,sort_order=?,updated_by=? WHERE id=?', [...$p,$id]); Audit::write((int)$u['id'],'SETTINGS_CHANGED','donation_accounts',$id,'Donation account updated'); }
        else { $id=Database::insert('INSERT INTO donation_accounts(title,bank_name,account_name,account_number,iban,swift_code,branch_name,currency,instructions,contact_name,contact_position,contact_phone,contact_email,is_active,sort_order,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[...$p,(int)$u['id']]); Audit::write((int)$u['id'],'CREATE','donation_accounts',$id,'Donation account created'); }
        if(isset($_POST['global_instructions'])) Database::exec('INSERT INTO settings(setting_group,setting_key,setting_value,is_public,updated_by) VALUES("donation","instructions",?,1,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)',[substr(trim($_POST['global_instructions']),0,5000),(int)$u['id']]);
        Session::flash('success','Donation page settings saved.'); redirect('admin/donation-settings'); }
    public function delete(): void { $this->requirePost(); $u=Auth::requireAdmin(); Auth::enforce('manage_settings'); $id=(int)($_POST['id']??0); if($id){Database::exec('UPDATE donation_accounts SET is_active=0,updated_by=? WHERE id=?',[(int)$u['id'],$id]);Audit::write((int)$u['id'],'UPDATE','donation_accounts',$id,'Donation account disabled');} Session::flash('success','Donation account disabled.');redirect('admin/donation-settings'); }
}
